/**
 * @method
 * @name ipt_chrgNm_onblur
 * @description ipt_chrgNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_chrgNm_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.chk_chrg_nm(selfVar, 20, '이름');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf00007.ipt_chrgNm_onblur' }); }
};

